/** User-provided portraits, resized with sips to 256×256 JPEG (quality 85). */
import { DEFAULT_AGENT_AVATAR_B64 } from './defaultAvatar.js';

const AVATARS: Record<string, string> = {
  xyra: DEFAULT_AGENT_AVATAR_B64,
  aria: '',
  recita: '',
};

export function builtinAgentAvatar(slug: string): { data: Buffer; mimeType: string } | null {
  const b64 = AVATARS[slug];
  return b64 ? { data: Buffer.from(b64, 'base64'), mimeType: 'image/jpeg' } : null;
}
